// Metrics blocks are fenced so their columns line up; the breakdown sits
// outside the fence because Slack will not render links inside a code block.
const pad  = (s, n) => String(s).padEnd(n);
const padL = (s, n) => String(s).padStart(n);
const rule = (t) => '\u2501\u2501\u2501 ' + t + ' \u2501\u2501\u2501';

const dur = (m) => {
  if (m == null || isNaN(m)) return '-';
  const t = Math.round(Number(m));
  const h = Math.floor(t / 60), mm = t % 60;
  return h > 0 ? h + 'h ' + mm + 'm' : mm + 'm';
};
const pct = (v) => (v == null || isNaN(v)) ? '-' : (Math.round(Number(v) * 10) / 10).toFixed(1) + '%';
const one = (v) => (v == null || isNaN(v)) ? '-' : (Math.round(Number(v) * 10) / 10).toFixed(1);

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/```/g, "'");

const cut = (s, n) => {
  const t = String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1).replace(/\s+\S*$/, '') + '\u2026' : t;
};

return $input.all().map(item => {
  const p = item.json;
  const m = p.metrics, a = p.automation;
  const base = String(p.zendesk_base || '').replace(/\/+$/, '');
  const tref = (id) => '<' + base + '/agent/tickets/' + id + '|#' + id + '>';

  // Any #1234567 the customer typed becomes a real link, otherwise Slack
  // swallows it as a channel or colour reference.
  const linkRefs = (s) => String(s).replace(/#(\d{4,12})/g, (mm, id) => tref(id));

  if (p.fetch_failed) {
    return { json: Object.assign({}, p, { slack_text:
      '\u26a0\ufe0f *CS Report \u00b7 ' + p.project_display_name + ' \u00b7 ' + p.report_date + '*\n' +
      'Could not retrieve tickets from Zendesk for this window, so no report was produced.\n' +
      'The other projects are unaffected. Check the failed execution in n8n.' }) };
  }

  const cite = (q) => '(Conv ' + tref(q.id) + ' / ' + esc(q.email) + ')';
  const quoteLine = (q, qlen) => '  \u25e6 "' + linkRefs(esc(cut(q.quote, qlen))) + '" ' + cite(q);

  const build = (qlen) => {
    const L = [];
    L.push('\ud83d\udcca *CS Report \u00b7 ' + p.project_display_name + ' \u00b7 ' + p.report_date + '*');
    L.push('```');
    // Cohort / status / excluded counts are deliberately not shown. They remain
    // on the node output for debugging. A broken rule set is an error rather
    // than a statistic, so that one line stays.
    if (p.exclude_rule_error) {
      L.push('! exclude_rules is not valid JSON - filter disabled');
      L.push('');
    }

    L.push(rule('METRICS'));
    L.push('\ud83d\udce5 ' + pad('Received:', 22) + padL(m.received, 5));
    L.push('\u2705 ' + pad('Solved:', 22) + padL(m.solved, 5));
    L.push('\ud83d\udcb8 ' + pad('Refunds:', 22) + padL(m.refunds, 5));
    L.push('\ud83c\udfaf ' + pad('Resolution Rate:', 22) + padL(pct(m.resolution_rate), 5));
    L.push('\u26a1 ' + pad('Avg First Response:', 22) + padL(dur(m.frt_avg), 5));
    L.push('\u23f1\ufe0f ' + pad('Avg Resolution:', 22) + padL(dur(m.res_avg), 5));
    L.push('\ud83d\udcac ' + pad('Avg Msgs/Conv:', 22) + padL(one(m.msgs_avg), 5));
    L.push('');

    if (p.automation_enabled) {
      L.push(rule('AUTOMATION'));
      const share = (n) => m.solved ? '   (' + pct((n / m.solved) * 100) + ' of solved)' : '';
      L.push(pad('Fully automated', 26) + padL(a.auto, 5) + share(a.auto));
      L.push(pad('Assisted (bot then human)', 26) + padL(a.assisted, 5) + share(a.assisted));
      L.push(pad('Fully manual', 26) + padL(a.manual, 5) + share(a.manual));
      L.push(pad('Automation touch rate', 26) + padL(pct(a.touch_rate), 5) + '   (of received)');
      if (!p.automation_tag) L.push('! No automation tag configured - assisted tickets count as manual.');
      L.push('');
    }

    L.push('\ud83d\udc64 Solved by Agent:');
    if (!p.agents.length) L.push(' - (none)');
    for (const ag of p.agents) L.push(' - ' + ag.name + ': ' + ag.count);
    L.push('```');

    // ---- breakdown, outside the fence so ticket links work -----------------
    const spam = (p.breakdown.find(b => b.key === 'spam') || {}).count || 0;
    L.push('*' + rule('REQUEST BREAKDOWN') + '*');
    L.push('Total: ' + p.total + ' \u00b7 Unique customers: ' + p.unique_customers + ' \u00b7 Spam: ' + spam);

    for (const b of p.breakdown) {
      if (!b.count) continue;
      const th = (p.themes || {})[b.key];
      L.push('');
      L.push(b.emoji + ' *' + b.label + '* \u2014 ' + b.count + ' (' + pct(b.pct) + ')' +
             (th ? ' \u2014 _' + esc(th) + '_' : ''));
      for (const q of ((p.quotes || {})[b.key] || [])) L.push(quoteLine(q, qlen));
    }

    if (p.unclassified) {
      L.push('');
      L.push('_' + p.unclassified + ' ticket(s) could not be classified and were counted under Onboarding._');
    }

    L.push('');
    L.push('*' + rule('TECHNICAL ISSUES') + '*');
    const rows = p.feature_rows || [];
    if (!(p.key_features || []).length) {
      L.push('_no key features configured for this project_');
    } else if (!rows.length) {
      L.push('_no feature-related technical tickets today_');
    } else {
      for (const r of rows) {
        let line = r.emoji + ' *' + esc(r.label) + '* \u2014 ' + r.count;
        if (r.quote) line += ' \u2014 "' + linkRefs(esc(cut(r.quote.quote, qlen))) + '" ' + cite(r.quote);
        L.push(line);
      }
    }
    return L.join('\n');
  };

  const baseLen = Number(p.quote_chars) || 300;
  let text = build(baseLen);
  if (text.length > 39000) {
    text = build(Math.max(120, Math.floor(baseLen / 2))) +
      '\n\n_[quotes shortened to fit Slack\u2019s message limit]_';
  }
  if (text.length > 39000) {
    text = text.slice(0, 38800) + '\n\n_[report truncated \u2013 lower the per-bucket quotas in the project config]_';
  }
  return { json: Object.assign({}, p, { slack_text: text }) };
});

// Runs once for ALL projects. One copy of the metrics logic, not eight.
return $input.all().map(item => {
  const pkg = item.json;
  const cfg = pkg.cfg || {};
  const CLASSIFY_CHARS = 4000;  // effectively the whole message; classification
                                // accuracy matters more than prompt size
  const BODY_CHARS     = 900;   // enough to extract a verbatim highlight from
  const QUOTE_CHARS    = Number(cfg.quote_chars) || 300;

  // ---- 1. Merge sources ----------------------------------------------------
  const base = {};
  for (const t of (pkg.tickets || [])) { if (t && t.id) base[t.id] = t; }

  const metricById = {};
  const userById   = {};
  for (const b of (pkg.meta || [])) {
    for (const t of (b.tickets || []))     if (t && t.id && base[t.id]) base[t.id] = Object.assign({}, base[t.id], t);
    for (const m of (b.metric_sets || [])) if (m && m.ticket_id) metricById[m.ticket_id] = m;
    for (const u of (b.users || []))       if (u && u.id) userById[u.id] = u;
  }

  const allTickets = Object.values(base).filter(t => t && t.id);
  const fetchFailed = !!pkg.fetch_failed;

  // ---- 1b. Report-only exclusions -----------------------------------------
  // QA bots and internal testers flood Zendesk but must not reach the report.
  // Matched tickets are dropped BEFORE any metric is computed, so they never
  // count towards Received, Solved, response times or the breakdown.
  let rules = {};
  let ruleError = '';
  try { rules = cfg.exclude_rules ? JSON.parse(cfg.exclude_rules) : {}; }
  catch (e) { rules = {}; ruleError = String((e && e.message) || 'invalid JSON'); }

  const list = (k) => Array.isArray(rules[k]) ? rules[k] : [];
  const lc = (s) => String(s == null ? '' : s).toLowerCase().trim();

  // Gmail plus-addressing: love.language827+123@gmail.com is the same mailbox
  // as love.language827@gmail.com, so both sides are normalised identically.
  const normEmail = (e) => {
    const s = lc(e);
    const at = s.lastIndexOf('@');
    if (at === -1) return s;
    let local = s.slice(0, at);
    const domain = s.slice(at + 1);
    const plus = local.indexOf('+');
    if (plus !== -1) local = local.slice(0, plus);
    if (domain === 'gmail.com' || domain === 'googlemail.com') local = local.replace(/\./g, '');
    return local + '@' + domain;
  };

  const rawEmailOf = (t) => {
    const u = userById[t.requester_id];
    return (u && u.email) ? lc(u.email) : '';
  };

  const isExcluded = (t) => {
    const raw = rawEmailOf(t);
    const nEmail = normEmail(raw);
    const domain = nEmail.slice(nEmail.lastIndexOf('@') + 1);
    const subject = lc(t.subject);
    const body = lc(t.description);
    const tags = Array.isArray(t.tags) ? t.tags.map(lc) : [];

    if (list('email_base').some(v => lc(v) && normEmail(v) === nEmail)) return true;
    if (list('email_domain').some(v => lc(v) && lc(v).replace(/^@/, '') === domain)) return true;
    if (list('email_contains').some(v => lc(v) && raw.indexOf(lc(v)) !== -1)) return true;
    if (list('subject_equals').some(v => lc(v) && subject === lc(v))) return true;
    if (list('subject_contains').some(v => lc(v) && subject.indexOf(lc(v)) !== -1)) return true;
    if (list('text_contains').some(v => lc(v) && body.indexOf(lc(v)) !== -1)) return true;
    if (list('requester_ids').some(v => Number(v) && Number(v) === Number(t.requester_id))) return true;
    if (list('tags').some(v => lc(v) && tags.indexOf(lc(v)) !== -1)) return true;
    for (const rx of list('regex')) {
      try {
        const re = new RegExp(rx, 'i');
        if (re.test(raw) || re.test(subject) || re.test(body)) return true;
      } catch (e) { /* a bad pattern is ignored rather than failing the run */ }
    }
    return false;
  };

  const tickets = [];
  let excluded = 0;
  for (const t of allTickets) { if (isExcluded(t)) excluded++; else tickets.push(t); }

  // ---- 2. Category handling ------------------------------------------------
  // Only refunds and cancellations come from the Zendesk category. Everything
  // else is classified from the message text downstream.
  const norm = (s) => String(s == null ? '' : s)
    .toLowerCase().trim()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '');

  const categoryOf = (t) => {
    const fid = Number(cfg.category_field_id);
    const f = (t.custom_fields || []).find(x => Number(x.id) === fid);
    return f && f.value != null && f.value !== '' ? String(f.value) : '';
  };

  const isRefund       = (t) => norm(categoryOf(t)).indexOf('refund') !== -1;
  const isCancellation = (t) => norm(categoryOf(t)).indexOf('cancellation') !== -1;
  const isZendeskSpam  = (t) => norm(categoryOf(t)) === 'spam';
  // Categories dropped outright: not a customer problem we report on.
  const isDuplicate    = (t) => norm(categoryOf(t)) === 'duplicate_contact';
  const isBilling      = (t) => norm(categoryOf(t)) === 'billing';

  // ---- 3. Automation classification ---------------------------------------
  const johnId  = Number(cfg.automation_agent_id) || 0;
  const autoTag = String(cfg.automation_tag || '').trim();
  const automationEnabled = johnId > 0;

  const isSolved    = (t) => t.status === 'solved' || t.status === 'closed';
  const johnSolved  = (t) => automationEnabled && Number(t.assignee_id) === johnId;
  const johnTagged  = (t) => !!(autoTag && Array.isArray(t.tags) && t.tags.indexOf(autoTag) !== -1);
  const johnTouched = (t) => johnSolved(t) || johnTagged(t);

  const classOf = (t) => {
    if (!automationEnabled) return 'manual';
    if (johnSolved(t)) return 'auto';
    if (johnTagged(t)) return 'assisted';
    return 'manual';
  };

  // ---- 4. Stats helpers ----------------------------------------------------
  const cal = (v) => (v && typeof v === 'object' && v.calendar != null) ? Number(v.calendar) : null;
  const avg = (a) => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;

  // ---- 5. METRICS block ----------------------------------------------------
  const received = tickets.length;
  const solved   = tickets.filter(isSolved);
  const refunds  = tickets.filter(isRefund).length;

  const frtVals = [], resVals = [], msgVals = [];
  let commentCountSeen = false;
  for (const t of tickets) {
    const m = metricById[t.id] || {};
    const a = cal(m.reply_time_in_minutes);
    if (a != null) frtVals.push(a);
    if (isSolved(t)) {
      const b = cal(m.full_resolution_time_in_minutes);
      if (b != null) resVals.push(b);
    }
    // Avg Msgs/Conv: true comment count via the comment_count sideload.
    // Falls back to agent replies + the customer's opening message.
    if (t.comment_count != null) { commentCountSeen = true; msgVals.push(Number(t.comment_count)); }
    else if (m.replies != null) { msgVals.push(Number(m.replies) + 1); }
  }

  // ---- 6. AUTOMATION block -------------------------------------------------
  const solvedByClass = { auto: 0, assisted: 0, manual: 0 };
  for (const t of solved) solvedByClass[classOf(t)]++;
  const touched = tickets.filter(johnTouched).length;

  // ---- 7. Solved by agent --------------------------------------------------
  const autoName = cfg.automation_agent_name || 'Automation';
  const agentCounts = {};
  for (const t of solved) {
    let name;
    if (t.assignee_id == null) name = 'Unassigned';
    else if (automationEnabled && Number(t.assignee_id) === johnId) name = autoName;
    else name = (userById[t.assignee_id] && userById[t.assignee_id].name) || ('User ' + t.assignee_id);
    agentCounts[name] = (agentCounts[name] || 0) + 1;
  }
  const agents = Object.keys(agentCounts)
    .map(name => ({ name, count: agentCounts[name] }))
    .sort((a, b) => {
      if (a.name === autoName) return -1;
      if (b.name === autoName) return 1;
      if (a.name === 'Unassigned') return 1;
      if (b.name === 'Unassigned') return -1;
      return b.count - a.count;
    });

  // ---- 8. Body cleaning ----------------------------------------------------
  // Strips quoted replies, signatures, forwarded blocks and continuation notes
  // so the model has clean prose to pull a highlight from.
  const cleanBody = (raw) => {
    const lines = String(raw == null ? '' : raw).split(/\r?\n/);
    const keep = [];
    for (const ln of lines) {
      if (/^\s*--\s*$/.test(ln)) break;
      if (/^\s*-{2,}\s*(original message|forwarded message)/i.test(ln)) break;
      if (/^\s*begin forwarded message/i.test(ln)) break;
      if (/^\s*>/.test(ln)) continue;
      if (/^\s*(from|sent|to|subject|date|cc)\s*:/i.test(ln)) continue;
      if (/^\s*on .{0,90}\bwrote:\s*$/i.test(ln)) continue;
      if (/continuation (of|from)\b/i.test(ln)) continue;
      if (/^\s*(sent|get) (from|outlook)\b/i.test(ln)) continue;
      keep.push(ln);
    }
    return keep.join(' ')
      .replace(/\s+/g, ' ')
      // drop a leading greeting so fallback quotes start at the real content
      .replace(/^\s*(hi|hello|hey|dear)\b[^.!?,]{0,30}[,.!]?\s*/i, '')
      .trim();
  };

  const squash = (s, n) => {
    const t = String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
    return t.length > n ? t.slice(0, n - 1).replace(/\s+\S*$/, '') + '\u2026' : t;
  };

  const zdBase = String(cfg.zendesk_base || '').replace(/\/+$/, '');
  const emailOf = (t) => {
    const u = userById[t.requester_id];
    return (u && u.email) ? u.email : ('user ' + t.requester_id);
  };

  const entry = (t) => {
    // A ticket that is nothing but a forwarded chain cleans down to an empty
    // string; fall back to the subject so no empty quote is ever rendered.
    const body = cleanBody(t.description) || squash(t.subject, 140) || '(no message body)';
    return {
      id: String(t.id),
      subject: squash(t.subject, 140),
      text: squash(body, CLASSIFY_CHARS),   // for classification
      body: squash(body, BODY_CHARS),       // for highlight extraction
      full: body,                           // for verbatim verification
      email: emailOf(t),
      url: zdBase + '/agent/tickets/' + t.id
    };
  };

  // ---- 9. Seed buckets & split out what needs classifying ------------------
  const seeded = { refunds: [], cancellations: [], spam: [] };
  const toClassify = [];
  let duplicates = 0;
  let billing = 0;

  for (const t of tickets) {
    if (isDuplicate(t)) { duplicates++; continue; }     // noise, excluded entirely
    if (isBilling(t))   { billing++; continue; }        // payment admin, not reported
    if (isRefund(t))       { seeded.refunds.push(entry(t)); continue; }
    if (isCancellation(t)) { seeded.cancellations.push(entry(t)); continue; }
    if (isZendeskSpam(t))  { seeded.spam.push(entry(t)); continue; }
    toClassify.push(entry(t));
  }

  let features = [];
  try { features = cfg.key_features ? JSON.parse(cfg.key_features) : []; } catch (e) { features = []; }

  return {
    project_key: cfg.project_key,
    project_display_name: cfg.project_display_name,
    gemini_model: cfg.gemini_model,
    report_date: cfg.report_date,
    run_at: cfg.run_at,
    fetch_failed: fetchFailed,
    automation_enabled: automationEnabled,
    automation_agent_name: autoName,
    automation_tag: autoTag,
    zendesk_base: zdBase,
    quote_chars: QUOTE_CHARS,
    quotas: {
      refunds:       Number(cfg.quota_refunds) || 3,
      cancellations: Number(cfg.quota_cancellations) || 3,
      product_value: Number(cfg.quota_product_value) || 5,
      onboarding:    Number(cfg.quota_onboarding) || 5,
      technical:     Number(cfg.quota_technical) || 5,
      spam:          Number(cfg.quota_spam) || 3
    },
    key_features: features,
    metrics: {
      received,
      solved: solved.length,
      refunds,
      resolution_rate: received ? (solved.length / received) * 100 : 0,
      frt_avg: avg(frtVals),
      res_avg: avg(resVals),
      msgs_avg: avg(msgVals),
      msgs_exact: commentCountSeen
    },
    automation: {
      auto: solvedByClass.auto,
      assisted: solvedByClass.assisted,
      manual: solvedByClass.manual,
      touch_rate: received ? (touched / received) * 100 : 0
    },
    agents,
    duplicates_excluded: duplicates,
    billing_excluded: billing,
    excluded_filtered: excluded,
    exclude_rule_error: ruleError,
    seeded,
    to_classify: toClassify
  };
}).map(json => ({ json }));

// Classifies every ticket that the Zendesk category cannot place into one of
// the four inferred buckets, and for technical tickets identifies which of the
// project's key features it concerns. Bucket and feature are both constrained
// by response-schema enums, so an invalid value cannot come back.
const NOOP_BODY = {
  contents: [{ role: 'user', parts: [{ text: 'Return the JSON object {"ok":true}.' }] }],
  generationConfig: {
    temperature: 0, maxOutputTokens: 64, responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { ok: { type: 'BOOLEAN' } }, required: ['ok'] }
  }
};
const projects = $input.all().map(i => i.json);
// Smaller chunks than before: each ticket now carries its full message rather
// than a 240-character preview.
const CHUNK = 40;

const SYSTEM = (featureList) => [
  'You classify customer support tickets for a software product.',
  'For each ticket you receive its full subject line and the full text of the message the customer sent.',
  'Assign every ticket to exactly one bucket.',

  'SCOPE RULE. Refund requests, chargebacks, payment problems and subscription cancellations are counted and reported separately, and must never drive your choice of bucket.',
  'Do not pick a bucket because the customer asked for their money back, disputed a charge, complained about being charged, or asked to cancel.',
  'Judge the ticket on the underlying problem the customer describes, not on what they are asking you to do about it.',
  'It is perfectly acceptable for a ticket to belong in no bucket at all. Prefer none over forcing a poor fit.',

  'product_value - the customer is dissatisfied with what the product actually gave them: the result, output or report is inaccurate, generic, thin, low quality, or not worth what they paid.',
  'Choose this when the substance of the complaint is the quality or the value of what they received.',
  'If a customer demands a refund and names a quality or value failing as the reason, classify on that failing and use this bucket.',

  'onboarding - the customer does not know how to use the product: how to begin, what to do next, how a particular feature works, what their plan includes, or another genuine question about the service.',
  'Choose this when the customer is asking a question rather than reporting something broken.',
  'Do not use this bucket as a catch-all. A refund, payment, billing or cancellation request is not a service enquiry.',

  'technical - the customer cannot get in, or cannot get hold of what they are entitled to, or something malfunctioned.',
  'This covers being unable to log in, register or reach an account; being unable to open, download or receive a deliverable or result; and any part of the product erroring, hanging, timing out, or producing nothing.',
  'Choose this when something is blocked or broken, as opposed to merely unclear.',

  'spam - unsolicited marketing, SEO or partnership outreach, automated notifications, or content unrelated to the product.',

  'none - the ticket fits none of the four. Use this when it is purely a refund, chargeback, payment or cancellation matter with no underlying product problem described, or when it otherwise falls outside all four definitions.',
  'A ticket assigned none is left out of the report entirely, which is an acceptable outcome.',

  'Tie-breakers. If a ticket could fit more than one bucket, choose the one matching the primary problem in the customer\'s own words.',
  'Ignore politeness, anger, threats and length; classify on substance.',
  'Do not reach for none as an easy way out: if the customer describes any product, access or usability problem alongside a commercial request, classify on that problem.',

  'Then set feature. If and only if the bucket is technical AND the ticket concerns one of the listed product features, set feature to that exact label.',
  'In every other case set feature to the exact string none.',
  featureList.length
    ? 'The product features are: ' + featureList.join('; ') + '.'
    : 'This product has no configured features, so feature must always be none.',
  'Return one entry per input ticket, reusing the ids exactly as given. Return JSON only.'
].join(' ');

const out = [];

for (const p of projects) {
  const tix = p.to_classify || [];
  const labels = (p.key_features || []).map(f => f.label).filter(Boolean);

  if (!tix.length) {
    out.push({ json: { project_key: p.project_key, job: 'noop', ids: [], model: p.gemini_model, request_body: NOOP_BODY } });
    continue;
  }

  const schema = {
    type: 'OBJECT',
    properties: {
      assignments: {
        type: 'ARRAY',
        items: {
          type: 'OBJECT',
          properties: {
            id: { type: 'STRING' },
            bucket: { type: 'STRING', enum: ['product_value', 'onboarding', 'technical', 'spam', 'none'] },
            feature: { type: 'STRING', enum: labels.concat(['none']) }
          },
          required: ['id', 'bucket', 'feature']
        }
      }
    },
    required: ['assignments']
  };

  for (let i = 0; i < tix.length; i += CHUNK) {
    const slice = tix.slice(i, i + CHUNK);
    const lines = slice.map(t => t.id + ' | ' + (t.subject || '(no subject)') + ' :: ' + (t.text || '')).join('\n');
    out.push({
      json: {
        project_key: p.project_key,
        job: 'classify',
        model: p.gemini_model,
        ids: slice.map(t => t.id),
        request_body: {
          systemInstruction: { parts: [{ text: SYSTEM(labels) }] },
          contents: [{ role: 'user', parts: [{ text: 'Tickets (' + slice.length + '):\n' + lines }] }],
          generationConfig: {
            temperature: 0,
            thinkingConfig: { thinkingLevel: 'low' },
            maxOutputTokens: 16384,
            responseMimeType: 'application/json',
            responseSchema: schema
          }
        }
      }
    });
  }
}

return out;

// Applies the classification and counts everything in code. Tickets the model
// failed to place fall back to onboarding, so the totals always reconcile.
const BUCKETS = [
  { key: 'refunds',       emoji: '\ud83d\udcb0', label: 'Refund Requests' },
  { key: 'cancellations', emoji: '\ud83d\udeab', label: 'Cancellations Requests' },
  { key: 'product_value', emoji: '\u2b50', label: 'Product Value & Quality Issues' },
  { key: 'onboarding',    emoji: '\ud83e\udded', label: 'Onboarding & Service Inquiries' },
  { key: 'technical',     emoji: '\ud83d\udd10', label: 'Access & Technical Issues' },
  { key: 'spam',          emoji: '\ud83d\udce2', label: 'Spam & Marketing' }
];
const LLM_BUCKETS = ['product_value', 'onboarding', 'technical', 'spam'];
const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};
const projects = $('Assemble All').all().map(i => i.json);
const jobs = $('Prep Classification').all().map(i => i.json);
const resp = $input.all();

const placed = {};   // project -> id -> {bucket, feature}
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i];
  if (!job || job.job !== 'classify') continue;
  const allowed = new Set((job.ids || []).map(String));
  const parsed = resp[i] ? readJson(resp[i]) : null;
  const arr = (parsed && Array.isArray(parsed.assignments)) ? parsed.assignments : [];
  placed[job.project_key] = placed[job.project_key] || {};
  for (const a of arr) {
    const id = String((a && a.id) != null ? a.id : '').trim();
    if (!id || !allowed.has(id)) continue;
    if (a.bucket !== 'none' && LLM_BUCKETS.indexOf(a.bucket) === -1) continue;
    placed[job.project_key][id] = {
      bucket: a.bucket,
      feature: (a.feature && a.feature !== 'none') ? String(a.feature) : null
    };
  }
}

return projects.map(p => {
  const grouped = {};
  BUCKETS.forEach(b => { grouped[b.key] = []; });

  // category-driven buckets
  grouped.refunds = (p.seeded.refunds || []).slice();
  grouped.cancellations = (p.seeded.cancellations || []).slice();
  grouped.spam = (p.seeded.spam || []).slice();

  const map = placed[p.project_key] || {};
  const featureOf = {};
  let unclassified = 0;
  let uncounted = 0;
  for (const t of (p.to_classify || [])) {
    const hit = map[t.id];
    // An explicit `none` drops the ticket from the report. A MISSING assignment
    // is a failure, not a decision, so it still falls back to onboarding.
    if (hit && hit.bucket === 'none') { uncounted++; continue; }
    const bucket = hit ? hit.bucket : 'onboarding';
    if (!hit) unclassified++;
    grouped[bucket].push(t);
    if (bucket === 'technical' && hit && hit.feature) featureOf[t.id] = hit.feature;
  }

  const total = BUCKETS.reduce((s, b) => s + grouped[b.key].length, 0);

  // Unique customers counted on requester email, which is per-requester.
  const emails = new Set();
  BUCKETS.forEach(b => grouped[b.key].forEach(t => emails.add(t.email)));

  const breakdown = BUCKETS.map(b => ({
    key: b.key, emoji: b.emoji, label: b.label,
    count: grouped[b.key].length,
    pct: total ? (grouped[b.key].length / total) * 100 : 0
  }));

  // technical feature tallies - counted here, never by the model
  const featCounts = {};
  for (const t of grouped.technical) {
    const f = featureOf[t.id];
    if (f) featCounts[f] = (featCounts[f] || 0) + 1;
  }
  const featureRows = (p.key_features || [])
    .filter(f => featCounts[f.label])
    .map(f => ({ emoji: f.emoji || '\ud83d\udd27', label: f.label, count: featCounts[f.label] }))
    .sort((a, b) => b.count - a.count);

  return { json: Object.assign({}, p, {
    grouped, breakdown, feature_of: featureOf, feature_rows: featureRows,
    total, unique_customers: emails.size, unclassified, uncounted
  }) };
});

// One call per populated bucket returning the theme line plus verbatim
// highlights, and one call per project for the technical feature quotes.
const NOOP_BODY = {
  contents: [{ role: 'user', parts: [{ text: 'Return the JSON object {"ok":true}.' }] }],
  generationConfig: {
    temperature: 0, maxOutputTokens: 64, responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { ok: { type: 'BOOLEAN' } }, required: ['ok'] }
  }
};
const projects = $input.all().map(i => i.json);

const HIGHLIGHT_RULES = [
  'A highlight must be copied verbatim from the ticket text you were given - character for character, no paraphrasing, no correcting spelling, no ellipses of your own.',
  'Choose the single sentence or clause that best conveys what the customer actually wants or complains about.',
  'Never quote boilerplate, greetings, signatures, forwarded content, or notes about the ticket being a continuation of another conversation.',
  'Keep a highlight under 240 characters; if the best sentence is longer, quote the most informative contiguous part of it.'
].join(' ');

const THEME_SYSTEM = [
  'You summarise a group of customer support tickets and pick the most informative examples.',
  'First write theme: one sentence of at most 20 words describing what these customers were actually contacting support about. Name the concrete driver, do not restate the group name, do not mention counts.',
  'Then choose up to the requested number of tickets that a product team would most benefit from reading, favouring specific, concrete, distinct problems over near-duplicates or pure emotion.',
  'For each, return the ticket id and a highlight.',
  HIGHLIGHT_RULES,
  'Return JSON only.'
].join(' ');

const THEME_SCHEMA = {
  type: 'OBJECT',
  properties: {
    theme: { type: 'STRING' },
    picks: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: { id: { type: 'STRING' }, highlight: { type: 'STRING' } },
        required: ['id', 'highlight']
      }
    }
  },
  required: ['theme', 'picks']
};

const FEATURE_SYSTEM = [
  'You pick one representative customer quote per product feature.',
  'You receive technical support tickets already grouped under the feature they concern.',
  'For each feature listed, return the id of the single most informative ticket and a highlight from it.',
  HIGHLIGHT_RULES,
  'Return exactly one entry per feature present in the input, using the feature label exactly as given. Return JSON only.'
].join(' ');

const out = [];

for (const p of projects) {
  const model = p.gemini_model;

  for (const b of p.breakdown) {
    const tix = (p.grouped || {})[b.key] || [];
    if (!tix.length) continue;
    const want = (p.quotas || {})[b.key] || 3;
    const lines = tix.map(t => t.id + ' | ' + (t.subject || '(no subject)') + ' :: ' + (t.body || '')).join('\n');
    out.push({
      json: {
        project_key: p.project_key, job: 'digest', bucket_key: b.key, model,
        ids: tix.map(t => t.id),
        request_body: {
          systemInstruction: { parts: [{ text: THEME_SYSTEM }] },
          contents: [{ role: 'user', parts: [{ text: 'Group: ' + b.label + '\nReturn at most ' + want + ' picks.\nTickets (' + tix.length + '):\n' + lines }] }],
          generationConfig: {
            temperature: 0.1, thinkingConfig: { thinkingLevel: 'low' },
            maxOutputTokens: 8192, responseMimeType: 'application/json',
            responseSchema: THEME_SCHEMA
          }
        }
      }
    });
  }

  // technical feature quotes
  const rows = p.feature_rows || [];
  if (rows.length) {
    const byFeature = {};
    for (const t of (p.grouped.technical || [])) {
      const f = (p.feature_of || {})[t.id];
      if (f) (byFeature[f] = byFeature[f] || []).push(t);
    }
    const blocks = rows.map(r => 'FEATURE: ' + r.label + '\n' +
      (byFeature[r.label] || []).slice(0, 40)
        .map(t => '  ' + t.id + ' | ' + (t.subject || '') + ' :: ' + (t.body || '')).join('\n')).join('\n\n');
    out.push({
      json: {
        project_key: p.project_key, job: 'features', bucket_key: null, model,
        ids: (p.grouped.technical || []).map(t => t.id),
        request_body: {
          systemInstruction: { parts: [{ text: FEATURE_SYSTEM }] },
          contents: [{ role: 'user', parts: [{ text: blocks }] }],
          generationConfig: {
            temperature: 0.1, thinkingConfig: { thinkingLevel: 'low' },
            maxOutputTokens: 8192, responseMimeType: 'application/json',
            responseSchema: {
              type: 'OBJECT',
              properties: {
                features: {
                  type: 'ARRAY',
                  items: {
                    type: 'OBJECT',
                    properties: {
                      feature: { type: 'STRING', enum: rows.map(r => r.label) },
                      id: { type: 'STRING' },
                      highlight: { type: 'STRING' }
                    },
                    required: ['feature', 'id', 'highlight']
                  }
                }
              },
              required: ['features']
            }
          }
        }
      }
    });
  }
}

if (!out.length) {
  out.push({ json: { project_key: (projects[0] && projects[0].project_key) || 'none',
